-- Local synthetic fixture only. Confirmed defaults/range/states; eligibility values and identities are test-only.
CREATE EXTENSION btree_gist; CREATE ROLE anon; CREATE ROLE authenticated;
CREATE SCHEMA auth; CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
GRANT USAGE ON SCHEMA auth TO authenticated;
INSERT INTO auth.users VALUES('10000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000002'),('10000000-0000-0000-0000-000000000003'),('10000000-0000-0000-0000-000000000004');
CREATE TABLE public.communities(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL,city text NOT NULL,status text DEFAULT 'pending');
CREATE TABLE public.brands(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL,category text NOT NULL,contact_name text NOT NULL,contact_phone text NOT NULL,contact_email text NOT NULL,status text NOT NULL DEFAULT 'pending');
CREATE TABLE public.venues(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,community_id bigint NOT NULL REFERENCES communities(id),name text NOT NULL,location_type text NOT NULL,capacity integer,has_power boolean NOT NULL DEFAULT false,fee integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'available');
CREATE TABLE public.bookings(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now(),venue_id bigint NOT NULL REFERENCES venues(id),brand_id bigint NOT NULL REFERENCES brands(id),start_time timestamptz NOT NULL,end_time timestamptz NOT NULL,status text NOT NULL DEFAULT 'pending',CONSTRAINT bookings_valid_time CHECK(end_time>start_time),CONSTRAINT bookings_no_overlap EXCLUDE USING gist(venue_id WITH =,tstzrange(start_time,end_time,'[)') WITH &&) WHERE(status=ANY(ARRAY['pending'::text,'confirmed'::text])));
CREATE TABLE public.platform_admins(user_id uuid PRIMARY KEY REFERENCES auth.users(id));
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
GRANT TRUNCATE ON public.bookings TO anon,authenticated;
